@startuml

class Bus {
  + number : int
}

class Trajectory {
  + destination : string
}

class Line {
  + number : int
}

class PriceCategory {
  + name : string
}

class MensoTicket {
  + validityDuration : int
}

class MensoTrip {
  + time : time
  + date : date
}

class Invoice {
  + totalAmount : double
  + discount : double
}

class Customer {
  + homeAddress : string
  + officeAddress : string
  + workingHours : string
}

class Ticket {
  + price : double
}

Bus "0..*" -- "0..*" Trajectory : used for
Line "1" -- "1..*" Trajectory : groups
Line "0..*" -- "0..1" PriceCategory
MensoTicket "1" -- "0..*" MensoTrip
MensoTrip "0..*" -- "1" Line
MensoTrip "1" -- "1" MensoTicket
MensoTrip "1" -- "1" Invoice
Invoice "1" -- "0..*" Customer
Customer "1" -- "0..*" MensoTicket
Customer "1" -- "0..*" Ticket

@enduml

